{"file_path":"/work/tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_an_unflagged_transcript():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"c": []}) == 0.0


def test_window_boundaries():
    assert flags_in_window([1, 2, 4], 2) == 6
    assert flags_in_window([1, 2, 4], 0) == 0
    assert flags_in_window([1, 2, 4], 10) == 7


def test_parse_fields_and_skipped_lines():
    lines = ["", " \t", "  # comment", " x , 3 , 0 ", " y , 4 , "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 3, "flagged": False},
        {"id": "y", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,day,1"])
def test_parse_error_includes_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "ok,2,0", " ", bad_line])


def test_duplicate_ids_keep_last_input_record_before_sorting():
    events = parse_transcript_log(["x,9,1", "b,4,1", "a,4,1", "x,2,0"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_counts_fill_gaps_and_ignore_outside_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 0]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["x,1,1", "y,7,0"]),
              "b": parse_transcript_log(["z,8,1"]), "c": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"a": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": None}], "b": [{"flagged": True}], "c": [],
              "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 9) == ["a", "b", "z"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 1.0), ("c", None), ("z", 0.0),
    ]


def test_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 2, 0, 4, -1, 2]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([-1, 0]) == 0
